write("app/src/main/java/org/unirevlab/security/analysis/AutoModEngine.kt", "package org.unirevlab.security.analysis\n\nimport java.util.Locale\nimport org.unirevlab.security.model.StaticAnalysisReport\n\n/**\n * Authorized demonstration modifier.\n *\n * It only targets methods from the analyzed application's own package, works on an exact SHA-bound\n * Patch Lab workspace, caps the number of behavior-changing edits, and produces a separately signed\n * laboratory APK. It does not emulate store purchases, preserve the original signer, or modify the\n * original APK in place.\n */\nobject AutoModEngine {\n    enum class Mode { RETURN_TRUE, RETURN_FALSE, RETURN_INT }\n\n    data class Action(\n        val id: String,\n        val category: String,\n        val dexEntry: String,\n        val classDescriptor: String,\n        val methodName: String,\n        val prototype: String,\n        val mode: Mode,\n        val intValue: Int? = null,\n        val confidence: Int,\n        val reason: String,\n    ) {\n        val target: String get() = \"$classDescriptor->$methodName$prototype\"\n        val methodKey: String get() = \"$dexEntry|$classDescriptor|$methodName|$prototype\"\n    }\n\n    data class Plan(\n        val artifactSha256: String,\n        val assessmentScore: Int,\n        val assessmentBand: String,\n        val actions: List<Action>,\n        val eligibleBeforeCap: Int,\n    )\n\n    data class ApplyResult(val applied: List<Action>)\n\n    internal data class Suggestion(\n        val mode: Mode,\n        val intValue: Int?,\n        val confidence: Int,\n        val reason: String,\n    )\n\n    fun plan(report: StaticAnalysisReport, workspace: PatchLabEngine.Workspace): Plan {\n        if (report.artifact.sha256.isNotBlank()) {\n            require(workspace.artifactSha256.equals(report.artifact.sha256, ignoreCase = true)) {\n                \"AutoMod заблокирован: workspace не совпадает с SHA-256 проанализированного APK\"\n            }\n        }\n        val packagePrefix = report.manifest?.packageName\n            ?.takeIf { it.isNotBlank() }\n            ?.replace('.', '/')\n            ?.let { \"L$it/\" }\n            ?: return Plan(workspace.artifactSha256, 0, \"MINIMAL\", emptyList(), 0)\n\n        val assessment = TamperAssessmentEngine.scan(report, workspace)\n        val candidates = assessment.hits.asSequence()\n            .filter {\n                it.dexEntry != null && it.classDescriptor != null && it.methodName != null && it.prototype != null\n            }\n            .filter { requireNotNull(it.classDescriptor).startsWith(packagePrefix) }\n            .mapNotNull { hit ->\n                val suggestion = suggest(\n                    category = hit.category,\n                    methodName = requireNotNull(hit.methodName),\n                    prototype = requireNotNull(hit.prototype),\n                    baseScore = hit.score,\n                ) ?: return@mapNotNull null\n                Action(\n                    id = \"automod-${hit.category.lowercase(Locale.ROOT)}-${requireNotNull(hit.methodName)}\",\n                    category = hit.category,\n                    dexEntry = requireNotNull(hit.dexEntry),\n                    classDescriptor = requireNotNull(hit.classDescriptor),\n                    methodName = requireNotNull(hit.methodName),\n                    prototype = requireNotNull(hit.prototype),\n                    mode = suggestion.mode,\n                    intValue = suggestion.intValue,\n                    confidence = suggestion.confidence,\n                    reason = suggestion.reason,\n                )\n            }\n            .distinctBy { it.methodKey }\n            .sortedWith(compareByDescending<Action> { it.confidence }.thenBy { it.target })\n            .toList()\n\n        val selected = selectDiverse(candidates)\n        return Plan(\n            artifactSha256 = workspace.artifactSha256,\n            assessmentScore = assessment.score,\n            assessmentBand = assessment.band,\n            actions = selected,\n            eligibleBeforeCap = candidates.size,\n        )\n    }\n\n    fun apply(workspace: PatchLabEngine.Workspace, plan: Plan, authorizationConfirmed: Boolean): ApplyResult {\n        require(authorizationConfirmed) {\n            \"AutoMod требует отдельного подтверждения права на модификацию этого APK\"\n        }\n        require(plan.artifactSha256.equals(workspace.artifactSha256, ignoreCase = true)) {\n            \"План AutoMod относится к другому APK\"\n        }\n        require(plan.actions.isNotEmpty()) { \"В плане AutoMod нет безопасно выбранных демонстрационных действий\" }\n        require(workspace.modifiedDexEntries.isEmpty() && workspace.replacements.isEmpty()) {\n            \"Для AutoMod нужен чистый workspace без ручных патчей/замен. Подготовьте workspace заново.\"\n        }\n\n        val edited = linkedMapOf<String, String>()\n        plan.actions.forEach { action ->\n            PatchLabEngine.disassembleDex(workspace, action.dexEntry)\n            val key = \"${action.dexEntry}|${action.classDescriptor}\"\n            val before = edited[key] ?: PatchLabEngine.loadClass(workspace, action.dexEntry, action.classDescriptor)\n            val after = when (action.mode) {\n                Mode.RETURN_TRUE -> PatchLabEngine.forceBooleanReturn(before, action.methodName, action.prototype, true)\n                Mode.RETURN_FALSE -> PatchLabEngine.forceBooleanReturn(before, action.methodName, action.prototype, false)\n                Mode.RETURN_INT -> forceIntReturn(\n                    before,\n                    action.methodName,\n                    action.prototype,\n                    requireNotNull(action.intValue),\n                )\n            }\n            edited[key] = after\n        }\n\n        // Save only after every transformation succeeds, so a failed plan does not leave a half-patched workspace.\n        edited.forEach { (key, text) ->\n            val parts = key.split('|', limit = 2)\n            PatchLabEngine.saveClass(workspace, parts[0], parts[1], text)\n        }\n        return ApplyResult(plan.actions)\n    }\n\n    internal fun suggestForTesting(\n        category: String,\n        methodName: String,\n        prototype: String,\n        baseScore: Int = 70,\n    ): Suggestion? = suggest(category, methodName, prototype, baseScore)\n\n    internal fun forceIntReturnForTesting(\n        classText: String,\n        methodName: String,\n        prototype: String,\n        value: Int,\n    ): String = forceIntReturn(classText, methodName, prototype, value)\n\n    private fun selectDiverse(candidates: List<Action>): List<Action> {\n        if (candidates.size <= MAX_ACTIONS) return candidates\n        val selected = mutableListOf<Action>()\n        CATEGORY_PRIORITY.forEach { category ->\n            candidates.firstOrNull { it.category == category && it !in selected }?.let(selected::add)\n            if (selected.size >= MAX_ACTIONS) return selected\n        }\n        candidates.forEach { action ->\n            if (selected.size >= MAX_ACTIONS) return@forEach\n            if (action !in selected) selected += action\n        }\n        return selected\n    }\n\n    private fun suggest(category: String, methodName: String, prototype: String, baseScore: Int): Suggestion? {\n        val tokens = identifierTokens(methodName)\n        val compact = tokens.joinToString(\"\")\n        if (prototype.endsWith(\")Z\")) {\n            val negative = NEGATIVE_BOOLEAN_MARKERS.any { marker -> marker in tokens || compact.contains(marker) }\n            val decisionPrefix = tokens.firstOrNull() in DECISION_PREFIXES\n            return when (category) {\n                \"ENTITLEMENT_TRUST\" -> {\n                    if (PENDING_MARKERS.any { it in tokens }) return null\n                    val signal = ENTITLEMENT_BOOLEAN_MARKERS.any { marker -> marker in tokens || compact.contains(marker) }\n                    if (!signal || !decisionPrefix) null\n                    else if (negative) {\n                        Suggestion(\n                            Mode.RETURN_FALSE,\n                            null,\n                            (baseScore + 8).coerceIn(0, 100),\n                            \"Демонстрация: отрицательное client-side entitlement-состояние принудительно возвращает false.\",\n                        )\n                    } else {\n                        Suggestion(\n                            Mode.RETURN_TRUE,\n                            null,\n                            (baseScore + 10).coerceIn(0, 100),\n                            \"Демонстрация: локальное решение о premium/access/entitlement принудительно возвращает true.\",\n                        )\n                    }\n                }\n\n                \"FEATURE_CONFIG\" -> {\n                    val signal = FEATURE_BOOLEAN_MARKERS.any { marker -> marker in tokens || compact.contains(marker) }\n                    if (!signal || !decisionPrefix) null\n                    else if (negative) {\n                        Suggestion(\n                            Mode.RETURN_FALSE,\n                            null,\n                            (baseScore + 4).coerceIn(0, 100),\n                            \"Демонстрация: локальный disabled/blocked feature-флаг принудительно возвращает false.\",\n                        )\n                    } else {\n                        Suggestion(\n                            Mode.RETURN_TRUE,\n                            null,\n                            (baseScore + 6).coerceIn(0, 100),\n                            \"Демонстрация: локальный feature/config gate принудительно возвращает true.\",\n                        )\n                    }\n                }\n\n                \"INTEGRITY\" -> {\n                    val signal = INTEGRITY_BOOLEAN_MARKERS.any { marker -> marker in tokens || compact.contains(marker) }\n                    if (!signal || !decisionPrefix) null\n                    else if (negative) {\n                        Suggestion(\n                            Mode.RETURN_FALSE,\n                            null,\n                            (baseScore + 8).coerceIn(0, 100),\n                            \"Демонстрация: client-side tamper/root/emulator/debugger сигнал принудительно возвращает false.\",\n                        )\n                    } else {\n                        Suggestion(\n                            Mode.RETURN_TRUE,\n                            null,\n                            (baseScore + 6).coerceIn(0, 100),\n                            \"Демонстрация: локальная integrity/signature/attestation проверка принудительно возвращает true.\",\n                        )\n                    }\n                }\n\n                \"LOCAL_STATE\" -> {\n                    val signal = LOCAL_BOOLEAN_MARKERS.any { marker -> marker in tokens || compact.contains(marker) }\n                    if (!signal || !decisionPrefix) null\n                    else if (\"dead\" in tokens || \"empty\" in tokens || \"depleted\" in tokens) {\n                        Suggestion(\n                            Mode.RETURN_FALSE,\n                            null,\n                            baseScore.coerceIn(0, 100),\n                            \"Демонстрация: локальное отрицательное state-решение принудительно возвращает false.\",\n                        )\n                    } else {\n                        Suggestion(\n                            Mode.RETURN_TRUE,\n                            null,\n                            baseScore.coerceIn(0, 100),\n                            \"Демонстрация: локальное state-решение принудительно возвращает true.\",\n                        )\n                    }\n                }\n\n                else -> null\n            }\n        }\n\n        if (category == \"LOCAL_STATE\" && prototype.lastReturnType() in setOf('I', 'S', 'B', 'C')) {\n            val selected = LOCAL_INT_VALUES.entries.firstOrNull { (term, _) -> term in tokens } ?: return null\n            return Suggestion(\n                Mode.RETURN_INT,\n                selected.value,\n                (baseScore + 4).coerceIn(0, 100),\n                \"Демонстрация: application-owned ${selected.key} getter получает фиксированное тестовое значение ${selected.value}.\",\n            )\n        }\n        return null\n    }\n\n    private fun String.lastReturnType(): Char? {\n        val index = lastIndexOf(')')\n        return if (index >= 0 && index + 1 < length) this[index + 1] else null\n    }\n\n    private fun identifierTokens(value: String): Set<String> {\n        val expanded = value.replace(Regex(\"([a-z0-9])([A-Z])\"), \"$1 $2\")\n        return expanded.lowercase(Locale.ROOT)\n            .split(Regex(\"[^a-z0-9]+\"))\n            .filter { it.isNotBlank() }\n            .toSet()\n    }\n\n    private fun forceIntReturn(classText: String, methodName: String, prototype: String, value: Int): String {\n        require(prototype.lastReturnType() in setOf('I', 'S', 'B', 'C')) {\n            \"AutoMod integer template поддерживает только int/short/byte/char return\"\n        }\n        require(value in Short.MIN_VALUE..Short.MAX_VALUE) { \"Тестовое значение не помещается в const/16\" }\n        val range = methodRange(classText, methodName, prototype)\n        val block = classText.substring(range)\n        val locals = LOCALS.find(block) ?: error(\"Метод не содержит .locals\")\n        val oldLocals = locals.groupValues[2].toInt()\n        require(oldLocals <= 254) { \"В методе слишком много локальных регистров\" }\n        val reg = oldLocals\n        val indent = locals.groupValues[1]\n        val marker = \"# UniRevLab AutoMod Demo\"\n        require(marker !in block) { \"AutoMod уже применён к этому методу\" }\n        val newLocalsLine = \"${indent}.locals ${oldLocals + 1}\"\n        val literal = if (value < 0) \"-0x${(-value).toString(16)}\" else \"0x${value.toString(16)}\"\n        val patch = buildString {\n            append('\\n')\n            append(indent).append(marker).append('\\n')\n            append(indent).append(\"const/16 v\").append(reg).append(\", \").append(literal).append('\\n')\n            append(indent).append(\"return v\").append(reg).append('\\n')\n        }\n        val updatedBlock = block.replaceRange(locals.range, newLocalsLine + patch)\n        return classText.replaceRange(range, updatedBlock)\n    }\n\n    private fun methodRange(text: String, methodName: String, prototype: String): IntRange {\n        val header = Regex(\"(?m)^\\\\.method[^\\\\n]*\\\\s${Regex.escape(methodName)}${Regex.escape(prototype)}\\\\s*$\")\n            .find(text) ?: error(\"Метод $methodName$prototype не найден в Smali-классе\")\n        val end = Regex(\"(?m)^\\\\.end method\\\\s*$\").find(text, header.range.last + 1)\n            ?: error(\"У метода $methodName$prototype нет .end method\")\n        return header.range.first..end.range.last\n    }\n\n    private val LOCALS = Regex(\"(?m)^(\\\\s*)\\\\.locals\\\\s+(\\\\d+)\\\\s*$\")\n    private val DECISION_PREFIXES = setOf(\"is\", \"has\", \"can\", \"allow\", \"allows\", \"check\", \"verify\", \"validate\", \"enable\", \"should\", \"may\")\n    private val NEGATIVE_BOOLEAN_MARKERS = setOf(\n        \"expired\", \"locked\", \"blocked\", \"denied\", \"disabled\", \"tampered\", \"rooted\", \"emulator\",\n        \"debug\", \"debugger\", \"hooked\", \"modified\", \"compromised\", \"fraud\", \"invalid\",\n    )\n    private val PENDING_MARKERS = setOf(\"pending\", \"processing\", \"acknowledging\", \"acknowledged\")\n    private val ENTITLEMENT_BOOLEAN_MARKERS = setOf(\n        \"premium\", \"pro\", \"vip\", \"paid\", \"subscription\", \"subscribed\", \"entitlement\", \"entitled\",\n        \"access\", \"owned\", \"unlocked\", \"licensed\", \"license\", \"trial\",\n    )\n    private val FEATURE_BOOLEAN_MARKERS = setOf(\"feature\", \"flag\", \"enabled\", \"available\", \"variant\", \"experiment\", \"config\")\n    private val INTEGRITY_BOOLEAN_MARKERS = setOf(\n        \"integrity\", \"tamper\", \"signature\", \"checksum\", \"attestation\", \"attest\", \"root\", \"rooted\",\n        \"emulator\", \"debug\", \"debugger\", \"hook\", \"hooked\", \"modified\", \"trusted\", \"valid\", \"verified\", \"secure\",\n    )\n    private val LOCAL_BOOLEAN_MARKERS = setOf(\"alive\", \"dead\", \"lives\", \"energy\", \"stamina\", \"ammo\", \"currency\", \"coins\", \"gems\")\n    private val LOCAL_INT_VALUES = linkedMapOf(\n        \"cooldown\" to 0,\n        \"rank\" to 1,\n        \"speed\" to 5,\n        \"health\" to 999,\n        \"hp\" to 999,\n        \"lives\" to 999,\n        \"energy\" to 999,\n        \"stamina\" to 999,\n        \"armor\" to 999,\n        \"damage\" to 999,\n        \"score\" to 9999,\n        \"balance\" to 9999,\n        \"coins\" to 9999,\n        \"coin\" to 9999,\n        \"gems\" to 9999,\n        \"gem\" to 9999,\n        \"currency\" to 9999,\n        \"wallet\" to 9999,\n        \"credits\" to 9999,\n    )\n    private val CATEGORY_PRIORITY = listOf(\"ENTITLEMENT_TRUST\", \"LOCAL_STATE\", \"FEATURE_CONFIG\", \"INTEGRITY\")\n    private const val MAX_ACTIONS = 4\n}\n")
write("app/src/main/java/org/unirevlab/security/ui/AutoModPanel.kt", "package org.unirevlab.security.ui\n\nimport android.content.Intent\nimport androidx.activity.compose.rememberLauncherForActivityResult\nimport androidx.activity.result.contract.ActivityResultContracts\nimport androidx.compose.foundation.layout.Arrangement\nimport androidx.compose.foundation.layout.Column\nimport androidx.compose.foundation.layout.Row\nimport androidx.compose.foundation.layout.fillMaxWidth\nimport androidx.compose.foundation.layout.padding\nimport androidx.compose.material3.Button\nimport androidx.compose.material3.Card\nimport androidx.compose.material3.CardDefaults\nimport androidx.compose.material3.Checkbox\nimport androidx.compose.material3.LinearProgressIndicator\nimport androidx.compose.material3.MaterialTheme\nimport androidx.compose.material3.OutlinedButton\nimport androidx.compose.material3.Text\nimport androidx.compose.runtime.Composable\nimport androidx.compose.runtime.getValue\nimport androidx.compose.runtime.mutableStateOf\nimport androidx.compose.runtime.produceState\nimport androidx.compose.runtime.remember\nimport androidx.compose.runtime.rememberCoroutineScope\nimport androidx.compose.runtime.setValue\nimport androidx.compose.ui.Modifier\nimport androidx.compose.ui.platform.LocalContext\nimport androidx.compose.ui.text.font.FontWeight\nimport androidx.compose.ui.unit.dp\nimport androidx.core.content.FileProvider\nimport java.io.File\nimport kotlinx.coroutines.Dispatchers\nimport kotlinx.coroutines.launch\nimport kotlinx.coroutines.withContext\nimport org.unirevlab.security.analysis.AutoModEngine\nimport org.unirevlab.security.analysis.PatchLabEngine\nimport org.unirevlab.security.model.StaticAnalysisReport\n\n@Composable\nfun AutoModPanel(\n    report: StaticAnalysisReport,\n    workspace: PatchLabEngine.Workspace,\n    busy: Boolean,\n    onAnalyzeBuilt: (File) -> Unit,\n    onStatus: (String) -> Unit,\n    onError: (String?) -> Unit,\n) {\n    val context = LocalContext.current\n    val scope = rememberCoroutineScope()\n    val plan by produceState<AutoModEngine.Plan?>(null, report.artifact.sha256, workspace.root.absolutePath) {\n        value = withContext(Dispatchers.IO) { AutoModEngine.plan(report, workspace) }\n    }\n    var rightsConfirmed by remember(workspace.artifactSha256) { mutableStateOf(false) }\n    var autoBusy by remember(workspace.artifactSha256) { mutableStateOf(false) }\n    var built by remember(workspace.artifactSha256) { mutableStateOf<PatchLabEngine.BuildResult?>(null) }\n\n    val exportPicker = rememberLauncherForActivityResult(\n        ActivityResultContracts.CreateDocument(\"application/vnd.android.package-archive\"),\n    ) { uri ->\n        val file = built?.signedApk\n        if (uri != null && file != null) {\n            scope.launch {\n                val result = runCatching {\n                    withContext(Dispatchers.IO) {\n                        context.contentResolver.openOutputStream(uri, \"wt\").use { output ->\n                            requireNotNull(output) { \"Не удалось открыть файл назначения\" }\n                            file.inputStream().buffered(128 * 1024).use { input ->\n                                input.copyTo(output, 128 * 1024)\n                            }\n                            output.flush()\n                        }\n                    }\n                }\n                result.onSuccess { onStatus(\"AutoMod APK экспортирован.\") }\n                    .onFailure { onError(it.message) }\n            }\n        }\n    }\n\n    Card(colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.errorContainer.copy(alpha = 0.22f))) {\n        Column(Modifier.padding(14.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {\n            Text(\"AutoMod Demo — наглядное доказательство\", fontWeight = FontWeight.Bold)\n            Text(\n                \"После отдельного подтверждения прав AutoMod меняет только высокосигнальные методы кода самого приложения: \" +\n                    \"локальные premium/access/feature/integrity boolean-gates и часть int-getter'ов локального state. \" +\n                    \"Максимум 4 точечных изменения. Исходный APK не меняется, подпись оригинала не сохраняется, store/billing не эмулируется.\",\n                style = MaterialTheme.typography.bodySmall,\n            )\n            Text(\n                \"Привязка: SHA-256 ${workspace.artifactSha256}\",\n                style = MaterialTheme.typography.bodySmall,\n            )\n\n            if (plan == null) {\n                LinearProgressIndicator(Modifier.fillMaxWidth())\n                Text(\"Формируем безопасный AutoMod-план…\", style = MaterialTheme.typography.bodySmall)\n            } else {\n                val current = requireNotNull(plan)\n                Text(\n                    \"Основа плана: calibrated score ${current.assessmentScore}/100 (${current.assessmentBand}); \" +\n                        \"подходящих целей до лимита: ${current.eligibleBeforeCap}; выбрано: ${current.actions.size}.\",\n                    style = MaterialTheme.typography.bodySmall,\n                )\n                if (current.actions.isEmpty()) {\n                    Text(\n                        \"Высокоуверенных app-owned целей для автоматической модификации не найдено. \" +\n                            \"Это не означает отсутствия риска — используйте ручной Patch Lab/trace.\",\n                        style = MaterialTheme.typography.bodySmall,\n                    )\n                } else {\n                    current.actions.forEach { action ->\n                        Card(colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface.copy(alpha = 0.72f))) {\n                            Column(Modifier.padding(9.dp), verticalArrangement = Arrangement.spacedBy(3.dp)) {\n                                Text(\n                                    \"${action.category} · confidence ${action.confidence}\",\n                                    fontWeight = FontWeight.SemiBold,\n                                    style = MaterialTheme.typography.bodySmall,\n                                )\n                                Text(action.target, style = MaterialTheme.typography.bodySmall)\n                                Text(\n                                    when (action.mode) {\n                                        AutoModEngine.Mode.RETURN_TRUE -> \"Патч: return true\"\n                                        AutoModEngine.Mode.RETURN_FALSE -> \"Патч: return false\"\n                                        AutoModEngine.Mode.RETURN_INT -> \"Патч: return ${action.intValue}\"\n                                    },\n                                    style = MaterialTheme.typography.bodySmall,\n                                )\n                                Text(action.reason, style = MaterialTheme.typography.bodySmall)\n                            }\n                        }\n                    }\n                }\n\n                val workspaceClean = workspace.modifiedDexEntries.isEmpty() && workspace.replacements.isEmpty()\n                if (!workspaceClean && built == null) {\n                    Text(\n                        \"AutoMod требует чистый workspace, чтобы доказательство и diff не смешивались с ручными изменениями. \" +\n                            \"Нажмите «Подготовить Patch Lab workspace» заново.\",\n                        color = MaterialTheme.colorScheme.error,\n                        style = MaterialTheme.typography.bodySmall,\n                    )\n                }\n\n                Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(8.dp)) {\n                    Checkbox(\n                        checked = rightsConfirmed,\n                        onCheckedChange = { rightsConfirmed = it },\n                        enabled = !busy && !autoBusy && built == null,\n                    )\n                    Text(\n                        \"Подтверждаю право/разрешение правообладателя на модификацию именно этого APK для демонстрационного теста.\",\n                        style = MaterialTheme.typography.bodySmall,\n                        modifier = Modifier.weight(1f),\n                    )\n                }\n\n                Button(\n                    onClick = {\n                        scope.launch {\n                            autoBusy = true\n                            built = null\n                            onError(null)\n                            onStatus(\"AutoMod: применяем проверенный план → Smali → DEX → APK → тестовая подпись…\")\n                            val result = runCatching {\n                                withContext(Dispatchers.IO) {\n                                    AutoModEngine.apply(workspace, current, rightsConfirmed)\n                                    PatchLabEngine.build(workspace)\n                                }\n                            }\n                            result.getOrNull()?.let {\n                                built = it\n                                onStatus(\"AutoMod Demo готов: ${current.actions.size} точечных изменений, APK собран и подписан тестовым ключом.\")\n                            }\n                            result.exceptionOrNull()?.let { onError(it.message) }\n                            autoBusy = false\n                        }\n                    },\n                    enabled = rightsConfirmed && current.actions.isNotEmpty() && workspaceClean && !busy && !autoBusy && built == null,\n                    modifier = Modifier.fillMaxWidth(),\n                ) {\n                    Text(\"Применить AutoMod и собрать тестовый APK\")\n                }\n            }\n\n            if (autoBusy) LinearProgressIndicator(Modifier.fillMaxWidth())\n\n            built?.let { result ->\n                Text(\"AutoMod тестовая сборка готова\", fontWeight = FontWeight.Bold)\n                Text(\"SHA-256: ${result.sha256}\", style = MaterialTheme.typography.bodySmall)\n                Text(\"Изменено: ${result.changedEntries.joinToString()}\", style = MaterialTheme.typography.bodySmall)\n                PatchBuildAuditPanel(report = report, workspace = workspace, result = result)\n                OutlinedButton(\n                    onClick = {\n                        val base = report.artifact.displayName.substringBeforeLast('.')\n                            .replace(Regex(\"[^A-Za-z0-9._-]\"), \"_\")\n                            .take(64)\n                        exportPicker.launch(\"${base}-unirevlab-automod.apk\")\n                    },\n                    modifier = Modifier.fillMaxWidth(),\n                ) { Text(\"Экспортировать AutoMod APK\") }\n                OutlinedButton(\n                    onClick = {\n                        runCatching {\n                            val uri = FileProvider.getUriForFile(\n                                context,\n                                \"${context.packageName}.fileprovider\",\n                                result.signedApk,\n                            )\n                            val intent = Intent(Intent.ACTION_VIEW)\n                                .setDataAndType(uri, \"application/vnd.android.package-archive\")\n                                .addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION or Intent.FLAG_ACTIVITY_NEW_TASK)\n                            context.startActivity(intent)\n                        }.onFailure { onError(it.message) }\n                    },\n                    modifier = Modifier.fillMaxWidth(),\n                ) { Text(\"Установить AutoMod тестовую сборку\") }\n                Button(\n                    onClick = { onAnalyzeBuilt(result.signedApk) },\n                    modifier = Modifier.fillMaxWidth(),\n                ) { Text(\"Повторно проанализировать AutoMod APK\") }\n            }\n        }\n    }\n}\n")
write("app/src/test/java/org/unirevlab/security/analysis/TamperAssessmentClassifierTest.kt", "package org.unirevlab.security.analysis\n\nimport org.junit.Assert.assertFalse\nimport org.junit.Assert.assertTrue\nimport org.junit.Test\n\nclass TamperAssessmentClassifierTest {\n    @Test\n    fun substringNoiseDoesNotBecomeSecurityCategory() {\n        val noise = listOf(\n            \"scoreboard\",\n            \"process\",\n            \"professional\",\n            \"profile\",\n            \"protobuf\",\n            \"prepaid\",\n            \"lifestyle\",\n            \"ranking\",\n            \"balanced\",\n            \"configuration\",\n        )\n        noise.forEach { value ->\n            assertTrue(\"$value should not classify\", TamperAssessmentEngine.categoriesForTesting(value).isEmpty())\n        }\n    }\n\n    @Test\n    fun camelCaseAndExactSecurityTermsStillClassify() {\n        assertTrue(\"LOCAL_STATE\" in TamperAssessmentEngine.categoriesForTesting(\"getHighScore\"))\n        assertTrue(\"ENTITLEMENT_TRUST\" in TamperAssessmentEngine.categoriesForTesting(\"isPro\"))\n        assertTrue(\"ENTITLEMENT_TRUST\" in TamperAssessmentEngine.categoriesForTesting(\"hasPremiumAccess\"))\n        assertTrue(\"FEATURE_CONFIG\" in TamperAssessmentEngine.categoriesForTesting(\"remoteConfig\"))\n        assertTrue(\"INTEGRITY\" in TamperAssessmentEngine.categoriesForTesting(\"rootCheck\"))\n        assertFalse(\"ENTITLEMENT_TRUST\" in TamperAssessmentEngine.categoriesForTesting(\"professional\"))\n    }\n\n    @Test\n    fun repeatedWeakArchiveSignalsDoNotExplodeOverallScore() {\n        val weak = (1..30).map { index ->\n            TamperAssessmentEngine.SurfaceHit(\n                category = \"LOCAL_STATE\",\n                kind = \"ARCHIVE_ENTRY\",\n                location = \"assets/file-$index.txt\",\n                preview = \"score\",\n                score = 52,\n                archiveEntry = \"assets/file-$index.txt\",\n            )\n        }\n        val strong = listOf(\n            TamperAssessmentEngine.SurfaceHit(\n                \"ENTITLEMENT_TRUST\", \"DEX_METHOD\", \"classes.dex:Lapp/A;->isPremium()Z\",\n                \"isPremium\", 70, \"classes.dex\", \"Lapp/A;\", \"isPremium\", \"()Z\",\n            ),\n            TamperAssessmentEngine.SurfaceHit(\n                \"ENTITLEMENT_TRUST\", \"DEX_METHOD\", \"classes.dex:Lapp/B;->hasAccess()Z\",\n                \"hasAccess\", 70, \"classes.dex\", \"Lapp/B;\", \"hasAccess\", \"()Z\",\n            ),\n            TamperAssessmentEngine.SurfaceHit(\n                \"ENTITLEMENT_TRUST\", \"DEX_METHOD\", \"classes.dex:Lapp/C;->isOwned()Z\",\n                \"isOwned\", 70, \"classes.dex\", \"Lapp/C;\", \"isOwned\", \"()Z\",\n            ),\n        )\n\n        val weakScore = TamperAssessmentEngine.assessmentScoreForTesting(weak)\n        val strongScore = TamperAssessmentEngine.assessmentScoreForTesting(strong)\n        assertTrue(\"weak repeated archive noise should stay below MEDIUM: $weakScore\", weakScore < 45)\n        assertTrue(\"corroborated code evidence should outrank weak archive noise\", strongScore > weakScore)\n        assertTrue(\"corroborated code evidence should reach MEDIUM: $strongScore\", strongScore >= 45)\n    }\n}\n")
write("app/src/test/java/org/unirevlab/security/analysis/FlagSweepClassifierRegressionTest.kt", "package org.unirevlab.security.analysis\n\nimport java.io.File\nimport java.util.zip.ZipEntry\nimport java.util.zip.ZipOutputStream\nimport kotlin.io.path.createTempDirectory\nimport org.junit.Assert.assertFalse\nimport org.junit.Assert.assertTrue\nimport org.junit.Test\n\nclass FlagSweepClassifierRegressionTest {\n    @Test\n    fun rejectsWordSubstringsButKeepsIdentifierTokens() {\n        val dir = createTempDirectory(\"flag-classifier-regression-\").toFile()\n        try {\n            val apk = File(dir, \"sample.apk\")\n            ZipOutputStream(apk.outputStream()).use { zip ->\n                fun entry(name: String, text: String) {\n                    zip.putNextEntry(ZipEntry(name))\n                    zip.write(text.toByteArray())\n                    zip.closeEntry()\n                }\n                entry(\n                    \"assets/noise.txt\",\n                    \"scoreboard process professional profile protobuf prepaid lifestyle ranking balanced configuration enabledness\",\n                )\n                entry(\n                    \"assets/positive.txt\",\n                    \"highScore isPremiumEnabled remoteConfigEnabled user_balance rootCheckPassed proMode\",\n                )\n            }\n            val workspace = PatchLabEngine.Workspace(\n                root = dir,\n                originalApk = apk,\n                artifactSha256 = \"test\",\n                apiLevel = 35,\n                minSdk = 26,\n                dexEntries = emptyList(),\n                nativeEntries = emptyList(),\n                archiveEntries = listOf(\"assets/noise.txt\", \"assets/positive.txt\"),\n            )\n\n            val result = FlagSweepEngine.scan(workspace)\n            val noisy = result.matches.filter { it.entryName == \"assets/noise.txt\" }\n            listOf(\"score\", \"pro\", \"paid\", \"life\", \"rank\", \"balance\", \"config\", \"enabled\").forEach { term ->\n                assertFalse(\"$term must not match inside ordinary words\", noisy.any { it.term.equals(term, true) })\n            }\n\n            val positive = result.matches.filter { it.entryName == \"assets/positive.txt\" }\n            assertTrue(positive.any { it.term.equals(\"score\", true) })\n            assertTrue(positive.any { it.term.equals(\"pro\", true) })\n            assertTrue(positive.any { it.term.equals(\"premium\", true) || it.term.equals(\"isPremium\", true) })\n            assertTrue(positive.any { it.term.equals(\"remoteConfig\", true) || it.term.equals(\"config\", true) })\n            assertTrue(positive.any { it.term.equals(\"balance\", true) })\n            assertTrue(positive.any { it.term.equals(\"rootCheck\", true) })\n        } finally {\n            dir.deleteRecursively()\n        }\n    }\n}\n")
write("app/src/test/java/org/unirevlab/security/analysis/AutoModEngineTest.kt", "package org.unirevlab.security.analysis\n\nimport org.junit.Assert.assertEquals\nimport org.junit.Assert.assertNull\nimport org.junit.Assert.assertTrue\nimport org.junit.Test\n\nclass AutoModEngineTest {\n    @Test\n    fun choosesSemanticallySafeBooleanDirections() {\n        assertEquals(\n            AutoModEngine.Mode.RETURN_TRUE,\n            AutoModEngine.suggestForTesting(\"ENTITLEMENT_TRUST\", \"isPremium\", \"()Z\")?.mode,\n        )\n        assertEquals(\n            AutoModEngine.Mode.RETURN_FALSE,\n            AutoModEngine.suggestForTesting(\"ENTITLEMENT_TRUST\", \"isTrialExpired\", \"()Z\")?.mode,\n        )\n        assertEquals(\n            AutoModEngine.Mode.RETURN_FALSE,\n            AutoModEngine.suggestForTesting(\"INTEGRITY\", \"isTampered\", \"()Z\")?.mode,\n        )\n        assertEquals(\n            AutoModEngine.Mode.RETURN_TRUE,\n            AutoModEngine.suggestForTesting(\"INTEGRITY\", \"verifySignature\", \"()Z\")?.mode,\n        )\n        assertNull(AutoModEngine.suggestForTesting(\"ENTITLEMENT_TRUST\", \"professional\", \"()Z\"))\n        assertNull(AutoModEngine.suggestForTesting(\"LOCAL_STATE\", \"scoreboard\", \"()I\"))\n    }\n\n    @Test\n    fun choosesBoundedLocalStateIntegerDemo() {\n        val suggestion = AutoModEngine.suggestForTesting(\"LOCAL_STATE\", \"getHighScore\", \"()I\")\n        assertEquals(AutoModEngine.Mode.RETURN_INT, suggestion?.mode)\n        assertEquals(9999, suggestion?.intValue)\n    }\n\n    @Test\n    fun intReturnPatchAddsOneLocalAndImmediateReturn() {\n        val input = \"\"\"\n            .class public Ldemo/Test;\n            .super Ljava/lang/Object;\n\n            .method public getScore()I\n                .locals 1\n                const/4 v0, 0x1\n                return v0\n            .end method\n        \"\"\".trimIndent()\n\n        val patched = AutoModEngine.forceIntReturnForTesting(input, \"getScore\", \"()I\", 9999)\n        assertTrue(patched.contains(\".locals 2\"))\n        assertTrue(patched.contains(\"# UniRevLab AutoMod Demo\"))\n        assertTrue(patched.contains(\"const/16 v1, 0x270f\"))\n        assertTrue(patched.contains(\"return v1\"))\n    }\n}\n")

